description:
Simulate how `LoadLibraryW` and `FreeLibrary` count references. Write a class

```cpp
class ModuleTable
{
public:
    explicit ModuleTable(std::set<std::string> filesOnDisk);
    int load(const std::string& name);     // like LoadLibraryW
    bool free(int handle);                 // like FreeLibrary
    int count(const std::string& name) const;
    bool isLoaded(const std::string& name) const;
};
```

- `load` returns `0` if the file is not on disk. Otherwise, if the module is not loaded yet, it is mapped and gets a new handle: 1 for the first module ever mapped, 2 for the next, and so on (never reused). If it is already loaded, its count goes up and the **same** handle is returned.
- `free` with a handle of a loaded module decreases its count; at 0 the module is unmapped. It returns `false` for a handle that is not loaded (including one already freed completely).
- `count` is the current reference count, 0 if not loaded.
- Names ignore case: `StoneMath.dll` and `stonemath.DLL` are the same module.

A module that is unmapped and loaded again gets a **new** handle, just as a real DLL may land at a new address.

starter.solution.cpp:
#include <map>
#include <set>
#include <string>

class ModuleTable
{
public:
    explicit ModuleTable(std::set<std::string> filesOnDisk) {}

    int load(const std::string& name) { return 0; }
    bool free(int handle) { return false; }
    int count(const std::string& name) const { return 0; }
    bool isLoaded(const std::string& name) const { return false; }
};

solution.solution.cpp:
#include <cctype>
#include <map>
#include <set>
#include <string>

class ModuleTable
{
public:
    explicit ModuleTable(std::set<std::string> filesOnDisk)
    {
        for (const std::string& f : filesOnDisk) m_disk.insert(lower(f));
    }

    int load(const std::string& name)
    {
        const std::string key{ lower(name) };
        if (!m_disk.count(key)) return 0;
        auto it{ m_loaded.find(key) };
        if (it == m_loaded.end()) it = m_loaded.emplace(key, Entry{ ++m_lastHandle, 0 }).first;
        ++it->second.count;
        return it->second.handle;
    }

    bool free(int handle)
    {
        for (auto it{ m_loaded.begin() }; it != m_loaded.end(); ++it)
        {
            if (it->second.handle != handle) continue;
            if (--it->second.count == 0) m_loaded.erase(it);
            return true;
        }
        return false;
    }

    int count(const std::string& name) const
    {
        const auto it{ m_loaded.find(lower(name)) };
        return it == m_loaded.end() ? 0 : it->second.count;
    }

    bool isLoaded(const std::string& name) const { return count(name) > 0; }

private:
    struct Entry { int handle; int count; };
    static std::string lower(std::string s)
    {
        for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return s;
    }
    std::set<std::string> m_disk;
    std::map<std::string, Entry> m_loaded;
    int m_lastHandle{ 0 };
};

unitTests:
TEST("missing file") { ModuleTable t{ { "a.dll" } }; CHECK_EQ(t.load("b.dll"), 0); CHECK(!t.isLoaded("b.dll")); }
TEST("load twice, same handle") { ModuleTable t{ { "StoneMath.dll" } }; const int a = t.load("StoneMath.dll"); const int b = t.load("stonemath.DLL"); CHECK_EQ(a, 1); CHECK_EQ(b, 1); CHECK_EQ(t.count("STONEMATH.dll"), 2); }
TEST("free down to zero") { ModuleTable t{ { "a.dll" } }; const int h = t.load("a.dll"); t.load("a.dll"); CHECK(t.free(h)); CHECK(t.isLoaded("a.dll")); CHECK(t.free(h)); CHECK(!t.isLoaded("a.dll")); CHECK(!t.free(h)); }
TEST("handles are not reused") { ModuleTable t{ { "a.dll", "b.dll" } }; const int a = t.load("a.dll"); const int b = t.load("b.dll"); CHECK_EQ(a, 1); CHECK_EQ(b, 2); t.free(a); CHECK_EQ(t.load("a.dll"), 3); }
TEST("free an unknown handle") { ModuleTable t{ { "a.dll" } }; CHECK(!t.free(42)); CHECK(!t.free(0)); }
TEST("count of an unloaded module") { ModuleTable t{ { "a.dll" } }; CHECK_EQ(t.count("a.dll"), 0); }

